import{_ as t,o,c as a,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Plan — FR 3.3.2: Update User Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/02-profile/3-3-2-update-user-profile/plan.md","filePath":"feature/srs/02-profile/3-3-2-update-user-profile/plan.md"}'),i={name:"feature/srs/02-profile/3-3-2-update-user-profile/plan.md"};function r(n,e,d,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[s(`<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-3-2-update-user-profile" tabindex="-1">Plan — FR 3.3.2: Update User Profile <a class="header-anchor" href="#plan-—-fr-3-3-2-update-user-profile" aria-label="Permalink to &quot;Plan — FR 3.3.2: Update User Profile&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> — Personal profile field updates (<code>PUT /api/v1/users/me</code>) and independent validated image uploads (<code>POST /api/v1/users/me/avatar</code>, <code>POST /api/v1/users/me/banner</code>) enforcing <code>BR-11</code>.</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>controller/user/UserController.java</code> (<code>PUT /api/v1/users/me</code>, <code>POST /api/v1/users/me/avatar</code>, <code>POST /api/v1/users/me/banner</code>)</td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>service/impl/user/UserServiceImpl.java</code> (<code>updateUserProfile</code>, <code>uploadAvatar</code>, <code>uploadBanner</code>), <code>service/impl/storage/S3FileStorageServiceImpl.java</code>, <code>util/ImageValidator.java</code></td></tr><tr><td style="text-align:left;"><strong>DTOs &amp; Errors</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>UpdateProfileRequest</code>, <code>UserProfileResponse</code>, <code>AvatarResponse</code>, <code>BannerResponse</code>, <code>ErrorCode</code> (<code>VALIDATION_ERROR</code>, <code>NO_FILE_PROVIDED</code>, <code>INVALID_FILE_TYPE</code>, <code>FILE_TOO_LARGE</code>, <code>UPLOAD_FAILED</code>)</td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>UserRepository.java</code> (PostgreSQL <code>users</code>), AWS S3 bucket (<code>avatars/</code>, <code>banners/</code>)</td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/profile/index.tsx</code>, <code>src/pages/profile/components/{ProfileEditForm,AvatarUploadModal,JobTitleSelect,SkillsChipSelect,LanguageChipSelect,LocationAutocomplete}.tsx</code>, <code>src/components/shared/BannerUploader.tsx</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>src/screens/settings/AccountSettingsScreen.tsx</code>, <code>src/services/userService.ts</code></td></tr></tbody></table><h2 id="_2-api-contract-partial-merge-semantics" tabindex="-1">2. API Contract &amp; Partial-Merge Semantics <a class="header-anchor" href="#_2-api-contract-partial-merge-semantics" aria-label="Permalink to &quot;2. API Contract &amp; Partial-Merge Semantics&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PUT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/users/me</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;accessToken&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Body</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> { fullName, phone?, professionalTitle?, bio?, portfolioUrls?, skills?, location?, socialLinks?, workingLanguage?, timezone?, notificationPreferences? }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-&gt; 200 ApiResponse&lt;UserProfileResponse&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/users/me/avatar   (multipart/form-data: file)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-&gt; 200 ApiResponse&lt;AvatarResponse&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/users/me/banner   (multipart/form-data: file)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-&gt; 200 ApiResponse&lt;BannerResponse&gt;</span></span></code></pre></div><ul><li><strong>Immutable Email Structural Guard (<code>BR-11</code>):</strong> <code>UpdateProfileRequest</code> contains no <code>email</code> field, structurally preventing email tampering.</li><li><strong>Safe JSONB Preferences Merge:</strong> <code>timezone</code> and <code>notificationPreferences</code> merge into existing <code>users.preferences</code> JSONB so updating <code>timezone</code> never wipes <code>notificationPreferences</code> (and vice versa).</li><li><strong>Decoupled Media Lifecycle:</strong> Avatar and banner uploads run independently via <code>S3FileStorageServiceImpl</code> after MIME + size (<code>&lt;= 5 MB</code>) validation (<code>ImageValidator</code>), deleting replaced S3 objects cleanly without rolling back saved text fields.</li></ul><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Profile Field Save (<code>PUT /api/v1/users/me</code>):</strong><ul><li>Validates <code>fullName</code> (<code>@NotBlank</code> -&gt; <code>400 VALIDATION_ERROR</code> <code>MSG02</code>).</li><li>Loads <code>User</code> by <code>@AuthenticationPrincipal</code> (<code>404 USER_NOT_FOUND</code> if missing), updates submitted columns (<code>fullName</code>, <code>phone</code>, <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code>, <code>workingLanguage</code>, etc.), merges non-null <code>timezone</code> / <code>notificationPreferences</code> into <code>preferences</code> JSONB, saves <code>User</code>, and returns <code>UserProfileResponse</code>.</li><li>Frontend updates <code>authStore.setUser(...)</code> and invalidates profile/completeness queries immediately without page reload.</li></ul></li><li><strong>Avatar / Banner Upload (<code>POST /api/v1/users/me/avatar</code>):</strong><ul><li>Validates file non-empty (<code>NO_FILE_PROVIDED</code>), <code>image/*</code> MIME &amp; magic bytes (<code>INVALID_FILE_TYPE</code>), and size <code>&lt;= 5 MB</code> (<code>FILE_TOO_LARGE</code>).</li><li>Uploads new object to S3, deletes prior S3 object if present, saves <code>user.avatarUrl</code>, and returns <code>AvatarResponse</code>.</li></ul></li></ol><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.3.2</code> — Update User Profile</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>PUT /api/v1/users/me · POST /api/v1/users/me/avatar · POST /api/v1/users/me/banner</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>UserController</code> -&gt; <code>UserServiceImpl, S3FileStorageServiceImpl, ImageValidator</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>users</code> (<code>preferences</code> JSONB); AWS S3 (<code>avatars/</code>, <code>banners/</code>)</td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-11</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>400 VALIDATION_ERROR</code> / <code>NO_FILE_PROVIDED</code> / <code>INVALID_FILE_TYPE</code> / <code>FILE_TOO_LARGE</code>, <code>401 UNAUTHORIZED</code></td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/profile/index.tsx</code>, <code>src/pages/profile/components/{ProfileEditForm,AvatarUploadModal,JobTitleSelect,SkillsChipSelect,LanguageChipSelect,LocationAutocomplete}.tsx</code>, <code>src/services/userService.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>src/screens/settings/AccountSettingsScreen.tsx</code>, <code>src/services/userService.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>profile.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>`,14)])])}const u=t(i,[["render",r]]);export{h as __pageData,u as default};
